    // identity bar
    h+='<div class="home-idbar'+(me?'':' warn')+'"><label>You are:</label><select onchange="setCurrentUser(this.value)">'+teamOptions(me)+'</select>'+(me?'':'<span style="font-size:12px;color:var(--tx-warn)">Pick your name so tasks can be assigned to you.</span>')+'<button class="btn sm gold" style="margin-left:auto" onclick="ntToggle()"><i class="ti ti-plus"></i> New task</button></div>';

    // new-task form
    h+='<div id="nt-form" class="nt-form"><div class="nt-grid"><div class="full"><label class="lbl">Assign to (one or more)</label><div id="nt-assignees" class="nt-assignees">'+teamCheckboxes()+'</div></div><div><label class="lbl">Due date</label><input type="date" id="nt-due"></div><div class="full"><label class="lbl">Task &amp; context</label><textarea id="nt-text" rows="2" placeholder="What needs doing, and any context…" style="width:100%;border:.5px solid var(--bdr2);border-radius:var(--r);padding:8px 10px;font-size:13px;color:var(--tx);background:var(--bg)"></textarea></div></div><button class="btn primary" onclick="ntSubmit()">Assign task</button> <button class="btn" onclick="ntToggle()">Cancel</button></div>';

    // ----- My tasks (assigned to me) -----
    h+='<div class="home-panel"><h3><i class="ti ti-checklist"></i> My tasks'+(me?'':' — set your name above')+'</h3>'+myTasksHtml()+'</div>';

    // ----- Tasks I assigned (still open) -----
    if(me){ var byMe=tasksBag().filter(function(t){ return t.creator===me && !t.done && t.assignee!==me; }); if(byMe.length){ h+='<div class="home-panel"><h3><i class="ti ti-user-check"></i> Waiting on others <span class="lnk">'+byMe.length+' open</span></h3>'; byMe.slice(0,10).forEach(function(t){ var d=parseDate(t.due); h+='<div class="home-row"><span class="dot" style="background:var(--tx3)"></span><div class="rl"><b>'+esc(t.text)+'</b><div class="meta">assigned to '+esc(t.assignee)+(d?' · due '+fmtShort(d):'')+'</div></div></div>'; }); h+='</div>'; } }

    // ----- Operations: today's operations summary -----
    if(showOps){
      var coToday=0,ciToday=0,openOps=0;
      try{ bks.forEach(function(b){ var co=parseDate(b.checkOut); if(co&&dbetween(today,co)===0)coToday++; var ci=parseDate(b.checkIn); if(ci&&dbetween(today,ci)===0)ciToday++; }); }catch(e){}
      try{ if(S.daily&&Array.isArray(S.daily.tasks)) openOps=S.daily.tasks.filter(function(t){return t&&!t.completed;}).length; }catch(e){}
