      h+='<div class="home-chip" onclick="hgo(\'ops\')"><i class="ti ti-login"></i><div><div class="n">'+ciToday+'</div><div class="l">Check-ins today</div></div></div>';
      h+='<div class="home-chip" onclick="hgo(\'ops\')"><i class="ti ti-list-check"></i><div><div class="n">'+openOps+'</div><div class="l">Open ops tasks</div></div></div>';
      h+='</div>';
    }

    // ----- Action cards -----
    var cards='';
    if(isOps){
      cards+=card('ti-calendar-event','Daily operations','Turnovers, check-ins &amp; tasks','ops');
      cards+=card('ti-chart-bar','Performance','Occupancy &amp; pricing snapshot','perf');
      cards+=card('ti-target','Leads','Pipeline &amp; enquiries','leads');
      cards+=card('ti-tag','Property info','Amenities, rules &amp; compliance','pinfo');
    } else if(isAcc){
      cards+=card('ti-checklist','Monthly close','Review &amp; clear each property','mt');
      cards+=card('ti-shield-check','Compliance health','Profiles, owners &amp; Law 5170','pinfo');
      cards+=card('ti-cash','Payments to chase','Reconcile received payouts','pay');
      cards+=card('ti-file-analytics','Owner reports','Prepare &amp; send statements','rpt');
      cards+=card('ti-target','Leads','Pipeline &amp; enquiries','leads');
      cards+=card('ti-chart-bar','Performance','Occupancy &amp; pricing snapshot','perf');
    } else {
      cards+=card('ti-checklist','Monthly close','Review &amp; clear each property','mt');
      cards+=card('ti-cash','Payments to chase','Reconcile received payouts','pay');
      cards+=card('ti-file-analytics','Owner reports','Prepare &amp; send statements','rpt');
      cards+=card('ti-calendar-event','Daily operations','Turnovers, check-ins &amp; tasks','ops');
      cards+=card('ti-chart-bar','Performance','Occupancy &amp; pricing snapshot','perf');
      cards+=card('ti-target','Leads','Pipeline &amp; enquiries','leads');
