    // ----- Accounting: month-close + compliance -----
    if(showAcc){
      var total=apts.length, closed=0;
      try{ var mc=(typeof S!=='undefined'&&S.monthlyClose)?S.monthlyClose:{}; var ym=today.getFullYear()+'-'+pad(today.getMonth()+1); apts.forEach(function(a){ if(mc[ym+'|'+a.id]||mc[a.id+'|'+ym]) closed++; }); if(closed===0 && mc[ym] && typeof mc[ym]==='object') closed=Object.keys(mc[ym]).length; }catch(e){}
