      h+='<div class="home-panel"><h3><i class="ti ti-checklist"></i> Monthly close — '+today.toLocaleString('en',{month:'long'})+' '+today.getFullYear()+'<span class="lnk" onclick="hgo(\'mt\')">Open Monthly Tasks →</span></h3><div class="mc-bar"><span style="width:'+pct+'%"></span></div><div class="mc-meta"><b>'+closed+'</b> of <b>'+total+'</b> properties cleared'+(total?(' · '+Math.max(0,total-closed)+' still to close'):'')+'</div></div>';
