      var withOwner=apts.filter(function(a){return a&&(a.ownerEmail||a.ownerEmail2||a.ownerEmail3);}).length;
      function chk(label,ok,detail,tab){ return '<div class="chk-row" onclick="hgo(\''+tab+'\')"><i class="ti '+(ok?'ti-circle-check chk-ok':'ti-alert-triangle chk-warn')+'"></i>'+label+'<span class="st '+(ok?'chk-ok':'chk-warn')+'">'+detail+'</span></div>'; }
      h+='<div class="home-panel"><h3><i class="ti ti-shield-check"></i> Compliance health<span class="lnk" onclick="hgo(\'pinfo\')">Property info →</span></h3>'+chk('Property profiles set (Private / B2B / Leased)', total>0&&withProfile>=total, withProfile+'/'+total, 'cfg')+chk('Owner email on file', total>0&&withOwner>=total, withOwner+'/'+total, 'cfg')+chk('Law 5170/2025 documents & house rules', false, 'Review', 'pinfo')+'</div>';
