  // Show the current user's tasks on the classic Dashboard tab too
  try{ var _origRenderDash=window.renderDash; if(typeof _origRenderDash==='function'){ window.renderDash=function(){ var r; try{ r=_origRenderDash.apply(this,arguments); }catch(e){} injectDashTasks(); return r; }; } }catch(e){}

